import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Ensure we build with hipcc on ROCm
os.environ.setdefault("CXX", "hipcc")

# hipBLAS-based GEMV. This often beats GEMM for (M x K) @ (K x 1)
# and avoids launching a full GEMM kernel.
source = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>

#include <hip/hip_runtime.h>
#include <hipblas/hipblas.h>

static inline hipblasHandle_t get_handle() {
    // One handle per process; hipBLAS handles are thread-safe for different streams
    static hipblasHandle_t handle = nullptr;
    static std::once_flag flag;
    std::call_once(flag, [](){
        hipblasCreate(&handle);
        hipblasSetPointerMode(handle, HIPBLAS_POINTER_MODE_HOST);
    });
    return handle;
}

torch::Tensor matvec_hipblas(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be CUDA/ROCm tensor");
    TORCH_CHECK(B.is_cuda(), "B must be CUDA/ROCm tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D (K,1)");

    // Force contiguous to guarantee expected layout.
    if (!A.is_contiguous()) A = A.contiguous();
    if (!B.is_contiguous()) B = B.contiguous();

    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    TORCH_CHECK(B.size(0) == K && B.size(1) == 1, "B must have shape (K,1)");

    auto out = torch::empty({M, 1}, A.options());

    // We interpret row-major A (M x K) as column-major A' (K x M) where A' = A^T.
    // Then compute out = (A')^T * x  => out = A * x.
    const int m = (int)K;   // rows of A' in col-major
    const int n = (int)M;   // cols of A'
    const int lda = (int)K; // leading dimension for col-major A'

    const float alpha = 1.0f;
    const float beta  = 0.0f;

    hipblasHandle_t handle = get_handle();
    auto stream = at::hip::getDefaultHIPStream();
    hipblasSetStream(handle, stream);

    const float* A_ptr = (const float*)A.data_ptr<float>();
    const float* x_ptr = (const float*)B.data_ptr<float>();
    float* y_ptr = (float*)out.data_ptr<float>();

    // x is length K, incx=1. y is length M, incy=1.
    hipblasStatus_t st = hipblasSgemv(handle,
                                     HIPBLAS_OP_T,
                                     m, n,
                                     &alpha,
                                     A_ptr, lda,
                                     x_ptr, 1,
                                     &beta,
                                     y_ptr, 1);
    TORCH_CHECK(st == HIPBLAS_STATUS_SUCCESS, "hipblasSgemv failed");

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matvec_hipblas", &matvec_hipblas, "matvec via hipBLAS SGEMV (FP32)");
}
'''

ext = load_inline(
    name='matvec_hipblas_ext',
    cpp_sources='',
    cuda_sources=source,
    functions=None,
    extra_cuda_cflags=['-O3'],
    extra_cflags=['-O3'],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # kernelbench inputs are CPU by default; move to GPU if needed
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        return ext.matvec_hipblas(A, B)


