import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Use hipcc for ROCm
os.environ.setdefault("CXX", "hipcc")

# Fused cross entropy for FP32 logits and int64 targets.
# Computes mean over batch.
cpp_source = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>
#include <c10/hip/HIPGuard.h>

// -------- utility reductions --------
__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_down(val, offset));
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down(val, offset);
    return val;
}

// block reduce using warp primitives, assumes blockDim.x is multiple of 32
__device__ __forceinline__ float block_reduce_max(float val) {
    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;

    val = warp_reduce_max(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < (blockDim.x >> 5)) ? shared[lane] : -INFINITY;
    if (wid == 0) val = warp_reduce_max(val);
    return val;
}

__device__ __forceinline__ float block_reduce_sum(float val) {
    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;

    val = warp_reduce_sum(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < (blockDim.x >> 5)) ? shared[lane] : 0.0f;
    if (wid == 0) val = warp_reduce_sum(val);
    return val;
}

// Kernel 1: per-sample loss = logsumexp - logit[target]
// logits: [B, C] contiguous row-major
__global__ void xent_per_sample_kernel(const float* __restrict__ logits,
                                      const int64_t* __restrict__ targets,
                                      float* __restrict__ losses,
                                      int B, int C) {
    int b = blockIdx.x;
    if (b >= B) return;

    const float* row = logits + ((int64_t)b) * C;

    // Compute max
    float tmax = -INFINITY;
    for (int j = threadIdx.x; j < C; j += blockDim.x) {
        tmax = fmaxf(tmax, row[j]);
    }
    float rmax = block_reduce_max(tmax);
    __syncthreads();

    // Compute sum exp
    float tsum = 0.0f;
    for (int j = threadIdx.x; j < C; j += blockDim.x) {
        tsum += __expf(row[j] - rmax);
    }
    float rsum = block_reduce_sum(tsum);

    if (threadIdx.x == 0) {
        int64_t t = targets[b];
        // defensive: clamp target
        if (t < 0) t = 0;
        if (t >= C) t = C - 1;
        float lse = logf(rsum) + rmax;
        float z = row[t];
        losses[b] = lse - z;
    }
}

// Kernel 2: reduce losses to one value (sum), one atomic per block
__global__ void reduce_sum_kernel(const float* __restrict__ losses,
                                 float* __restrict__ out,
                                 int N) {
    float sum = 0.0f;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int i = idx; i < N; i += stride) sum += losses[i];
    sum = block_reduce_sum(sum);
    if (threadIdx.x == 0) atomicAdd(out, sum);
}

torch::Tensor cross_entropy_mean_hip(torch::Tensor logits, torch::Tensor targets) {
    TORCH_CHECK(logits.is_cuda(), "logits must be CUDA/HIP tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be CUDA/HIP tensor");
    TORCH_CHECK(logits.dtype() == torch::kFloat32, "logits must be float32");
    TORCH_CHECK(targets.dtype() == torch::kInt64, "targets must be int64");
    TORCH_CHECK(logits.dim() == 2, "logits must be 2D [B, C]");
    TORCH_CHECK(targets.dim() == 1, "targets must be 1D [B]");

    const auto B = (int)logits.size(0);
    const auto C = (int)logits.size(1);
    TORCH_CHECK((int)targets.size(0) == B, "targets size mismatch");

    const at::cuda::CUDAGuard device_guard(logits.device());

    auto losses = torch::empty({B}, torch::TensorOptions().dtype(torch::kFloat32).device(logits.device()));
    auto out = torch::zeros({}, torch::TensorOptions().dtype(torch::kFloat32).device(logits.device()));

    // Heuristic: 256 threads for C=4096 is good; one block per sample
    const int threads = 256;
    const dim3 blocks1(B);

    hipLaunchKernelGGL(xent_per_sample_kernel, blocks1, dim3(threads), 0, at::cuda::getDefaultCUDAStream(),
                       logits.data_ptr<float>(), targets.data_ptr<int64_t>(), losses.data_ptr<float>(), B, C);

    // Reduction kernel
    const int threads2 = 256;
    int blocks2 = (B + threads2 - 1) / threads2;
    // cap blocks to reduce atomics
    if (blocks2 > 256) blocks2 = 256;

    hipLaunchKernelGGL(reduce_sum_kernel, dim3(blocks2), dim3(threads2), 0, at::cuda::getDefaultCUDAStream(),
                       losses.data_ptr<float>(), out.data_ptr<float>(), B);

    // mean
    out = out / (float)B;
    return out;
}

