maxpool2d_cpp_source = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <vector>
#include <limits>

__global__ void maxpool2d_fwd_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    int N, int C, int H, int W,
    int outH, int outW,
    int kH, int kW,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW)
{
    int idx = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int total = N * C * outH * outW;
    if (idx >= total) return;

    int ow = idx % outW;
    int t = idx / outW;
    int oh = t % outH;
    t /= outH;
    int c = t % C;
    int n = t / C;

    int hstart = oh * strideH - padH;
    int wstart = ow * strideW - padW;

    float vmax = -INFINITY;

    // k is small (here 4). Unroll a bit with fixed bounds, break if exceeded.
    #pragma unroll
    for (int kh = 0; kh < 8; ++kh) {
        if (kh >= kH) break;
        int ih = hstart + kh * dilH;
        if ((unsigned)ih >= (unsigned)H) continue;
        #pragma unroll
        for (int kw = 0; kw < 8; ++kw) {
            if (kw >= kW) break;
            int iw = wstart + kw * dilW;
            if ((unsigned)iw >= (unsigned)W) continue;
            int in_idx = ((n * C + c) * H + ih) * W + iw;
            float v = x[in_idx];
            vmax = v > vmax ? v : vmax;
        }
    }

    y[idx] = vmax;
}

torch::Tensor maxpool2d_hip(torch::Tensor x,
                           int64_t k,
                           int64_t stride,
                           int64_t padding,
                           int64_t dilation) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/ROCm tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only FP32 supported");
    TORCH_CHECK(x.dim() == 4, "expected NCHW 4D input");

    auto x_contig = x.contiguous();

    int64_t N = x_contig.size(0);
    int64_t C = x_contig.size(1);
    int64_t H = x_contig.size(2);
    int64_t W = x_contig.size(3);

    int64_t kH = k;
    int64_t kW = k;
    int64_t strideH = stride;
    int64_t strideW = stride;
    int64_t padH = padding;
    int64_t padW = padding;
    int64_t dilH = dilation;
