import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ.setdefault("CXX", "hipcc")

# Use hipBLAS SGEMV. Key for performance: assume inputs are already on GPU and contiguous
# (KernelBench harness provides CUDA tensors for GPU targets).
source = r'''
#include <torch/extension.h>
#include <ATen/hip/HIPContext.h>

#include <hipblas/hipblas.h>
#include <mutex>

static inline hipblasHandle_t get_handle() {
    static hipblasHandle_t handle = nullptr;
    static std::once_flag flag;
    std::call_once(flag, [](){
        hipblasCreate(&handle);
        hipblasSetPointerMode(handle, HIPBLAS_POINTER_MODE_HOST);
    });
    return handle;
}

torch::Tensor matvec_hipblas(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA/ROCm tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 && B.scalar_type() == torch::kFloat32, "FP32 only");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "A and B must be contiguous");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A 2D, B 2D");

    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    TORCH_CHECK(B.size(0) == K && B.size(1) == 1, "B must be (K,1)");

    auto out = torch::empty({M, 1}, A.options());

    // Interpret row-major A (M x K) as column-major A' (K x M) with A' = A^T.
    // Compute out = (A')^T * x => A * x.
    const int m = (int)K;
    const int n = (int)M;
    const int lda = (int)K;

    const float alpha = 1.0f;
    const float beta  = 0.0f;

    hipblasHandle_t handle = get_handle();
    hipblasSetStream(handle, at::hip::getDefaultHIPStream());

    const float* A_ptr = (const float*)A.data_ptr<float>();
    const float* x_ptr = (const float*)B.data_ptr<float>();
    float* y_ptr = (float*)out.data_ptr<float>();

    hipblasStatus_t st = hipblasSgemv(handle,
                                     HIPBLAS_OP_T,
                                     m, n,
                                     &alpha,
                                     A_ptr, lda,
                                     x_ptr, 1,
                                     &beta,
                                     y_ptr, 1);
    TORCH_CHECK(st == HIPBLAS_STATUS_SUCCESS, "hipblasSgemv failed");

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matvec_hipblas", &matvec_hipblas, "matvec via hipBLAS SGEMV (FP32)");
}
'''

