maxpool2d_cpp_source = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <vector>
#include <limits>

// Specialized fast kernel for the benchmark's fixed parameters:
// k=4, stride=1, padding=1, dilation=1, NCHW FP32.
// Uses shared-memory tiling to drastically reduce redundant global reads.

constexpr int TILE = 16;
constexpr int K = 4;
constexpr int SH = TILE + (K - 1); // 19
constexpr int SW = TILE + (K - 1); // 19

__global__ void maxpool2d_k4s1p1_fwd_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    int NC, int H, int W,
    int outH, int outW)
{
    int nc = (int)blockIdx.z;
    int n = nc / (NC); // dummy, unused

    // We actually pass NC as C, and use blockIdx.z for n*c linear index.
    // Keep variables explicit below.

    int tile_oh0 = (int)blockIdx.y * TILE;
    int tile_ow0 = (int)blockIdx.x * TILE;

    int tx = (int)threadIdx.x; // 0..15
    int ty = (int)threadIdx.y; // 0..15

    // Decode n and c from linear index blockIdx.z
    int c = nc % NC;
    n = nc / NC;

    // Shared patch corresponds to input region starting at (tile_oh0 - pad, tile_ow0 - pad)
    constexpr int pad = 1;
    int in_h0 = tile_oh0 - pad;
    int in_w0 = tile_ow0 - pad;

    __shared__ float sh[SH][SW];

    int tid = ty * TILE + tx; // 0..255
    int sh_elems = SH * SW;   // 361

    // Load shared patch
    for (int i = tid; i < sh_elems; i += TILE * TILE) {
        int sy = i / SW;
        int sx = i - sy * SW;
        int ih = in_h0 + sy;
        int iw = in_w0 + sx;
        float v = -INFINITY;
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)W) {
            // x is contiguous NCHW
            int in_idx = ((n * NC + c) * H + ih) * W + iw;
            v = x[in_idx];
        }
        sh[sy][sx] = v;
    }

    __syncthreads();

    int oh = tile_oh0 + ty;
    int ow = tile_ow0 + tx;
    if (oh >= outH || ow >= outW) return;

    // For output (ty,tx), pooling window in shared starts at [ty][tx]
    float vmax = sh[ty][tx];
    vmax = fmaxf(vmax, sh[ty][tx + 1]);
    vmax = fmaxf(vmax, sh[ty][tx + 2]);
    vmax = fmaxf(vmax, sh[ty][tx + 3]);

    vmax = fmaxf(vmax, sh[ty + 1][tx]);
    vmax = fmaxf(vmax, sh[ty + 1][tx + 1]);
    vmax = fmaxf(vmax, sh[ty + 1][tx + 2]);
    vmax = fmaxf(vmax, sh[ty + 1][tx + 3]);

    vmax = fmaxf(vmax, sh[ty + 2][tx]);
    vmax = fmaxf(vmax, sh[ty + 2][tx + 1]);
    vmax = fmaxf(vmax, sh[ty + 2][tx + 2]);
    vmax = fmaxf(vmax, sh[ty + 2][tx + 3]);

    vmax = fmaxf(vmax, sh[ty + 3][tx]);
    vmax = fmaxf(vmax, sh[ty + 3][tx + 1]);
    vmax = fmaxf(vmax, sh[ty + 3][tx + 2]);
    vmax = fmaxf(vmax, sh[ty + 3][tx + 3]);

    int out_idx = ((n * NC + c) * outH + oh) * outW + ow;
    y[out_idx] = vmax;
}

torch::Tensor maxpool2d_hip(torch::Tensor x,
                           int64_t k,
                           int64_t stride,
                           int64_t padding,
                           int64_t dilation) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/ROCm tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only FP32 supported");
    TORCH_CHECK(x.dim() == 4, "expected NCHW 4D input");

    // Specialize for the benchmark configuration.
    TORCH_CHECK(k == 4 && stride == 1 && padding == 1 && dilation == 1,
                "This optimized kernel only supports k=4,stride=1,padding=1,dilation=1");

    auto x_contig = x.contiguous();

    int64_t N = x_contig.size(0);
    int64_t C = x_contig.size(1);
    int64_t H = x_contig.size(2);
    int64_t W = x_contig.size(3);

    int64_t outH = (H + 2 * padding - dilation * (k - 1) - 1) / stride + 1;
    int64_t outW = (W + 2 * padding - dilation * (k - 1) - 1) / stride + 1;

    auto y = torch::empty({N, C, outH, outW}, x_contig.options());

    dim3 threads(TILE, TILE, 1); // 256 threads
    dim3 blocks((unsigned)((outW + TILE - 1) / TILE),
                (unsigned)((outH + TILE - 1) / TILE),
                (unsigned)(N * C));

    hipStream_t stream = at::hip::getDefaultHIPStream();

    hipLaunchKernelGGL(maxpool2d_k4s1p1_fwd_kernel,
                       blocks, threads,
                       0, stream,
                       (const float*)x_contig.data_ptr<float>(),
                       (float*)y.data_ptr<float>(),
                       (int)C, (int)H, (int)W,
                       (int)outH, (int)outW);

    return y;
}

