# Optimized sum reduction over dim=1 (keepdim=True) for FP32 3D tensors.
# Key optimization vs naive: make global loads coalesced by assigning threads across D2,
# and split D1 reduction across a small Ty dimension within each block.

hip_src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void sum_dim1_coalesced_kernel(const float* __restrict__ x,
                                         float* __restrict__ out,
                                         int B, int D1, int D2) {
    // Block layout: x-dimension spans output columns (k), y-dimension spans partial reducers over D1.
    constexpr int TX = 256; // threads along k
    constexpr int TY = 2;   // reducers along D1

    int tx = (int)threadIdx.x; // 0..TX-1
    int ty = (int)threadIdx.y; // 0..TY-1

    int tile_k = (int)blockIdx.x;
    int b = (int)blockIdx.y;
    int k = tile_k * TX + tx;
    if (k >= D2) return;

    float acc = 0.0f;

    // base points at x[b, 0, k]
    const float* base = x + ((long)b * D1 * D2 + k);

    // Stride across D1; for each i, the TX threads read a contiguous segment.
    // Each thread only reads its k.
    for (int i = ty; i < D1; i += TY) {
        acc += base[(long)i * D2];
    }

    __shared__ float partial[TY][TX];
    partial[ty][tx] = acc;
    __syncthreads();

    if (ty == 0) {
        float sum = partial[0][tx];
        #pragma unroll
        for (int r = 1; r < TY; r++) sum += partial[r][tx];
        out[(long)b * D2 + k] = sum;
    }
}

torch::Tensor sum_dim1_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor [B, D1, D2]");

    auto x_contig = x.contiguous();
    int64_t B = x_contig.size(0);
    int64_t D1 = x_contig.size(1);
    int64_t D2 = x_contig.size(2);

    auto out = torch::empty({B, 1, D2}, x_contig.options());

    constexpr int TX = 256;
    constexpr int TY = 2;

    dim3 block(TX, TY, 1);
    dim3 grid((unsigned int)((D2 + TX - 1) / TX), (unsigned int)B, 1);

    hipStream_t stream = at::hip::getDefaultHIPStream();
    hipLaunchKernelGGL(sum_dim1_coalesced_kernel, grid, block, 0, stream,
                       (const float*)x_contig.data_ptr<float>(),
                       (float*)out.data_ptr<float>(),
                       (int)B, (int)D1, (int)D2);

    return out;
}

